void dispatch(){
 const unsigned int rows=sizeof(DISPATCH)/sizeof(DISPATCH[0]);assert(rows==222);
 unsigned int count[5]={0,0,0,0,0};unsigned int band_set[37]={0},band_clear[37]={0};
 const std::uint32_t entries[5]={0x18c06,0x18caa,0x18efa,0x18fd2,0x192c4};
 for(unsigned int i=0;i<rows;++i){const std::uint32_t*r=DISPATCH[i];
  Bytes ram=zero_ram();record(ram,REC,r[2],r[1],r[4],0x5a5a,0xa5a5);put(ram,REC+10,2,r[3]);put(ram,REC+12,2,4);
  putf(ram,0x53b8,2,r[5]);putf(ram,0x53ba,2,r[6]);const Bytes before=ram;
  State s=state(r[0]);s.carry=ms5::AnimationCarryClear;
  for(unsigned int j=0;j<8;++j)s.d[j]=0xabcd0000U+j*0x10001U;
  s.d[0]=r[7];s.d[1]=r[8];s.d[2]=r[9];s.d[3]=r[10];s.d[7]=r[11];
  const std::uint32_t a[8]={0x87654320,REC,0x87654324,0x87654326,0x87654328,A5,0x8765432c,SP};for(unsigned int j=0;j<8;++j)s.a[j]=a[j];
  State want=s;for(unsigned int j=0;j<8;++j)want.d[j]=r[12+j];want.a[7]=SP+4;want.pc=STOP;want.carry=carry_of(r[20]);
  Out o;assert(run(ram,s,STOP,o)&&quiet(o));if(!same(s,want)){std::cerr<<std::hex<<"dispatch "<<r[0]<<" type "<<r[1]<<"\n";show(s,want);}
  assert(same(s,want)&&ram==before);
  for(unsigned int e=0;e<5;++e)if(r[0]==entries[e])++count[e];
  if(r[0]==0x18c06)assert(r[20]==(r[1]<0x58||r[1]==0x90?2U:1U)); // type 90 -> 18c9e
  else if(r[0]==0x192c4){assert(r[20]!=0);if(r[20]==2)++band_set[r[1]/4];else ++band_clear[r[1]/4];}
  else assert(r[20]==0);}
 assert(count[0]==37&&count[1]==37&&count[2]==37&&count[3]==37&&count[4]==74);
 for(unsigned int k=0;k<37;++k)assert(band_set[k]==1&&band_clear[k]==1);
 // Types outside the table follow the computed PC: ffff -> table-1 (odd), fffe -> the JMP extension WORD
 // (interior), 8000 -> table-8000 (no executor), 0001 -> odd.
 const std::uint32_t tables[5]={0x18c0e,0x18cb2,0x18f02,0x18fda,0x192cc};
 for(unsigned int e=0;e<5;++e){
  const std::uint32_t types[4]={0xffff,0xfffe,0x8000,0x0001};
  const char*messages[4]={"unaligned animation machine PC","unsupported animation motion walk PC","unsupported animation machine PC","unaligned animation machine PC"};
  for(unsigned int t=0;t<4;++t){Bytes ram=zero_ram();put(ram,REC+2,2,types[t]);reject(ram,state(entries[e]),STOP,messages[t]);}
  // Type 90: the first PC after the 36 slots is a block start in every table (18c9e 18d42 18f92 1906a 1935c).
  Bytes ram=zero_ram();put(ram,REC+2,2,0x90);State s=state(entries[e]);Out o;
  const std::uint32_t next[5]={0x18c9e,0x18d42,0x18f92,0x1906a,0x1935c};
  assert(run(ram,s,next[e],o)&&quiet(o)&&s.pc==tables[e]+0x90U&&s.d[4]==0x90);}
}

