// U2 -> U3 -> U2 split runs from the natural seed shape: the U3 entries are ordinary stops and the frame
// reaches the 1a7a8 (U4 entry) stop with the same result continuous or split.
Bytes natural_ram(){
 Bytes ram=zero_ram();
 putf(ram,0x541e,2,0x0100);putf(ram,0x5420,2,0x0080);putf(ram,0x5440,2,0x0200);putf(ram,0x5442,2,0x0040);
 putf(ram,0x5444,2,0x8000);putf(ram,0x5448,2,0x1111);putf(ram,0x5426,2,0x0011);putf(ram,0x542a,2,0x0022);
 putf(ram,0x5446,2,0x0033);putf(ram,0x544a,2,0x0044);
 putf(ram,0x53bc,4,0x00500000);putf(ram,0x53c0,4,0x00300000);putf(ram,0x53a2,2,0x0010);putf(ram,0x53a6,2,0x0008);
 putf(ram,0x53ce,2,0x7fff);putf(ram,0x53d2,2,0x8000);putf(ram,0x53d0,2,0x7fff);putf(ram,0x53d4,2,0x8000);
 putf(ram,0x53fc,4,0x00001000);putf(ram,0x5400,4,0xfffff000);putf(ram,0x53b8,2,0x0050);putf(ram,0x53ba,2,0x0031);
 putf(ram,0x5418,2,0x0003);putf(ram,0x5408,4,0x00080000);putf(ram,0x5404,2,0x0002);
 record(ram,MOT,0,0x14,2,0,0);record(ram,MOT+10,0x10,0x40,2,0,0);record(ram,MOT+20,0x30,0x14,2,0,0);put(ram,MOT+30,2,0x50);put(ram,MOT+32,2,0xffff);
 putf(ram,0x53b4,4,MOT);return ram;}
void handover(){
 Bytes whole=natural_ram();State w=state(0x1a73c);Out o;assert(run(whole,w,0x1a7a8,o)&&o.ports.size()==2&&port(o,0,0x2ffff2,0x2000)&&port(o,1,0x2ffff0,0));
 assert(w.a[7]==SP-4&&get(whole,SP-4,4)==0x1a78c&&w.carry==ms5::AnimationCarryUnknown);
 // Order in the frame: 19b96 (19832->19844, 19c22, 19978->198ee->19910), 19d08 (19802->19812, 19d98->19910 twice),
 // 1a76a (19802->19812), 1a776.
 const std::uint32_t stops[]={0x19844,0x19c22,0x19910,0x19812,0x19910,0x19910,0x19812,0x1a776,0x1a7a8};
 Bytes ram=natural_ram();State s=state(0x1a73c);
 for(unsigned int i=0;i<sizeof(stops)/sizeof(stops[0]);++i){Out q;assert(run(ram,s,stops[i],q)&&s.pc==stops[i]);}
 assert(same(s,w)&&ram==whole);
 // The 1a0b6 script boundary is not reached (null script): the frame runs through U4 (1a7a8) to its RTS and rolls
 // back at the STOP return address, including the PVC writes.
 reject(natural_ram(),state(0x1a73c),0x1a0b6,"unsupported animation machine PC");
 // A non-null script with an open gate stops at 1a0b6 before any U3 walk.
 {Bytes r=natural_ram();putf(r,0x5412,4,0x10eb00);putf(r,0x5416,2,3);put(r,0x10eb00,2,1);State t=state(0x1a73c);Out q;
  assert(run(r,t,0x1a0b6,q)&&getf(r,0x53b4,4)==MOT&&getf(r,0x53b8,2)==0x50);}
}
