void zero_step(){
 for(unsigned int c=0;c<3;++c)for(unsigned int i=0;i<ROWS;++i){Bytes ram=zero_ram();State s=state(TABLE[i][0]);s.carry=carry_of(c);
  const Bytes before=ram;const State old=s;Out o;assert(run(ram,s,TABLE[i][0],o)&&same(s,old)&&ram==before&&quiet(o));}
}
void carry(){
 assert(ROWS==370&&KEEPS==211);unsigned int keeps=0;
 for(unsigned int i=0;i<ROWS;++i){const std::uint32_t pc=TABLE[i][0];const bool keep=member(KEEP,KEEPS,pc);if(keep)++keeps;
  const bool consumer=TABLE[i][1]!=TABLE[i][2];assert(consumer==member(CONSUMERS,9,pc)&&(!consumer||keep));
  for(unsigned int c=0;c<3;++c){if(consumer&&c==0)continue; // errors()
   Bytes ram=zero_ram();State s=state(pc);s.carry=carry_of(c);const std::uint32_t stop=c==2?TABLE[i][2]:TABLE[i][1];Out o;
   if(!run(ram,s,stop,o)||s.pc!=stop)std::cerr<<std::hex<<"row "<<pc<<"\n";
   assert(s.pc==stop&&quiet(o));
   ms5::AnimationCarryState expect=keep?carry_of(c):ms5::AnimationCarryUnknown;
   if(member(SETS,6,pc))expect=ms5::AnimationCarrySet;
   if(member(CLEARS,5,pc))expect=ms5::AnimationCarryClear;
   if(s.carry!=expect)std::cerr<<std::hex<<"carry row "<<pc<<"\n";assert(s.carry==expect);}}
 assert(keeps==KEEPS);
 for(unsigned int i=0;i<6;++i)assert(!member(KEEP,KEEPS,SETS[i]));
 for(unsigned int i=0;i<5;++i)assert(!member(KEEP,KEEPS,CLEARS[i]));
 // 19710/1971c with the other outcome: time != 0 -> RTS with Clear; next type bit 15 -> ORI Set.
 {Bytes ram=zero_ram();put(ram,REC,2,5);put(ram,REC+12,2,0x8000);State s=state(0x19710);s.carry=ms5::AnimationCarrySet;Out o;
  assert(run(ram,s,STOP,o)&&s.carry==ms5::AnimationCarryClear);
  s=state(0x1971c);s.carry=ms5::AnimationCarryClear;assert(run(ram,s,STOP,o)&&s.carry==ms5::AnimationCarrySet);}
 // 18c06 through every slot: C=1 for types 00..54, C=0 for 58..8c.
 for(unsigned int k=0;k<36;++k){Bytes ram=zero_ram();put(ram,REC+2,2,4*k);State s=state(0x18c06);s.carry=ms5::AnimationCarryUnknown;Out o;
  assert(run(ram,s,STOP,o)&&s.carry==(k<22?ms5::AnimationCarrySet:ms5::AnimationCarryClear));}
}
